+      height: 8px;
+      border-radius: 50%;
+      background: var(--primary);
+      content: "";
+    }
+
+    h1 {
+      margin: 0;
+      font-size: clamp(2rem, 7vw, 3rem);
+      line-height: 1.03;
+      letter-spacing: -0.06em;
+    }
+
+    .intro {
+      max-width: 38rem;
+      margin: 14px 0 30px;
+      color: var(--muted);
+      font-size: 1rem;
+      line-height: 1.65;
+    }
+
+    .form-field {
+      margin: 0 0 26px;
+      padding: 22px;
+      border: 1px solid var(--border);
+      border-radius: 22px;
+      background: var(--surface-muted);
+    }
+
+    legend {
+      padding: 0;
+      margin-bottom: 16px;
+      color: var(--text);
+      font-size: 1.12rem;
+      font-weight: 750;
+    }
+
+    .radio-group {
+      display: grid;
+      gap: 12px;
+    }
+
+    .radio-option {
+      position: relative;
+      display: flex;
+      align-items: center;
+      gap: 13px;
+      padding: 16px;
+      border: 1px solid var(--border);
+      border-radius: 18px;
+      background: var(--surface);
+      color: var(--text);
+      cursor: pointer;
+      transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease;
+    }
+
+    .radio-option:hover {
+      border-color: rgba(79, 70, 229, 0.42);
+      box-shadow: 0 12px 28px rgba(79, 70, 229, 0.1);
+      transform: translateY(-1px);
+    }
+
+    .radio-option input {
+      width: 20px;
+      height: 20px;
+      margin: 0;
+      accent-color: var(--primary);
+    }
+
+    .radio-option:has(input:checked) {
+      border-color: var(--primary);
+      box-shadow: 0 0 0 4px var(--ring);
+    }
+
+    .radio-label {
+      display: grid;
+      gap: 2px;
+      font-weight: 700;
+    }
+
+    .radio-hint {
+      color: var(--muted);
+      font-size: 0.88rem;
+      font-weight: 500;
+    }
+
+    .submit-button {
+      width: 100%;
+      border: 0;
+      border-radius: 18px;
+      padding: 16px 20px;
+      background: linear-gradient(135deg, var(--primary), #7c3aed);
+      color: white;
+      cursor: pointer;
+      font: inherit;
+      font-weight: 800;
+      box-shadow: 0 16px 28px rgba(79, 70, 229, 0.28);
+      transition: box-shadow 180ms ease, transform 180ms ease, background 180ms ease;
+    }
+
+    .submit-button:hover {
+      background: linear-gradient(135deg, var(--primary-dark), #6d28d9);
+      box-shadow: 0 18px 34px rgba(79, 70, 229, 0.34);
+      transform: translateY(-1px);
+    }
+
+    .submit-button:focus-visible,
+    .radio-option input:focus-visible {
+      outline: 3px solid var(--ring);
+      outline-offset: 3px;
+    }
+
+    @media (max-width: 520px) {
+      .form-card {
+        padding: 24px;
+        border-radius: 24px;
+      }
+
+      .form-field {
+        padding: 18px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main id="root" class="app-shell"></main>
+
+  <script>
+    const notificationOptions = [
