+      },
+      {
+        value: "sms",
+        label: "SMS",
+        hint: "Great for urgent, concise alerts."
+      },
+      {
+        value: "push",
+        label: "Push Notifications",
+        hint: "Instant updates on your devices."
+      }
+    ];
+
