        hint: "Great for urgent, concise alerts."
      },
      {
        value: "push",
        label: "Push Notifications",
        hint: "Instant updates on your devices."
      }
    ];

    function RadioOption({ value, label, hint }) {
      return `
        <label class="radio-option">
          <input type="radio" name="notificationPreference" value="${value}" required>
          <span class="radio-label">
            <span>${label}</span>
            <span class="radio-hint">${hint}</span>
          </span>
        </label>
      `;
    }

